preConditionHook:
// Brooks's "50 to 75 percent of the average daily range" threshold for
// deciding a trend is over, used as a protective stop: exit once the open
// loss reaches adrFraction of the recent average daily range. Book values 0.5
// to 0.75; default 0.6.
//
// Not AtrProfitTarget or AtrTrailingStop: those scale by a rolling N-BAR ATR,
// this by an N-SESSION high-low range, and this is a fixed protective stop
// rather than a target or a trail. The AverageDailyRange block is INLINED
// here rather than referenced, as the corpus does with named composites.
//
// THE AVERAGE DAILY RANGE BLOCK, identical to AverageDailyRange.json: walk
// back from bar 1, skip bars carrying the current date so today's incomplete
// session is excluded, group the rest by wall-clock date, and average the
// last dayLookback completed sessions' high-low. A mean of high-low with no
// gap term, not an ATR of daily bars. The dayLookback guard WRAPS the date
// read rather than being ANDed with it, because EasyLanguage does not
// short-circuit and the twins must touch the same history. Deepest index
// maxScanBars + 1; maxScanBars must cover dayLookback sessions of bars (on a
// daily or 1440-minute series one bar is one session, so dayLookback + 1).
//
// While the average is not yet available the stop is inert -- adrReady gates
// the exit, so a warm-up bar cannot exit at a zero distance.
//
// Direction-agnostic: a stop distance in dollars is the same both sides.
// BigPointValue is the raw contract multiplier and is NOT currency-converted
// while OpenPositionProfit is, as in AtrProfitTarget.
adrSum = 0.0;
adrDays = 0;
dHi = 0.0;
dLo = 0.0;
dOpen = false;
for (int kk = 1; kk <= (int)maxScanBars; ++kk) {
    if (el_lt((double)adrDays, dayLookback)) {
        if (day_of(ctx.Time(kk)) != day_of(ctx.Time(0))) {
            if (!dOpen) {
                dHi = high[kk];
                dLo = low[kk];
                dOpen = true;
            } else {
                if (el_gt(high[kk], dHi)) dHi = high[kk];
                if (el_lt(low[kk], dLo)) dLo = low[kk];
            }
            if (day_of(ctx.Time(kk + 1)) != day_of(ctx.Time(kk))) {
                adrSum = adrSum + (dHi - dLo);
                adrDays = adrDays + 1;
                dOpen = false;
            }
        }
    }
}
adrReady = el_ge((double)adrDays, dayLookback);
if (adrReady) {
    adr = adrSum / dayLookback;
} else {
    adr = 0.0;
}
